function validate([points]) {
  if (!Array.isArray(points) || points.length !== 3) return 'points needs exactly 3 points.';
  for (const point of points) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each coordinate is a whole number from 0 to 100.';
  }
  return null;
}

