function isBoomerang(points) {
  const [x1, y1] = points[0];
  const [x2, y2] = points[1];
  const [x3, y3] = points[2];
  const dx1 = x2 - x1;
  const dy1 = y2 - y1;
  const dx2 = x3 - x1;
  const dy2 = y3 - y1;
  const cross = dx1 * dy2 - dy1 * dx2;
  return cross !== 0;
}

