function isBoomerang(points) {
  const same = (p, q) => p[0] === q[0] && p[1] === q[1];
  if (same(points[0], points[1]) || same(points[0], points[2]) || same(points[1], points[2])) return false;
  // Reduce each direction from the first point to its smallest integer step with a fixed sign.
  const gcd = (a, b) => (b === 0 ? Math.abs(a) : gcd(b, a % b));
  const step = (p, q) => {
    let dx = q[0] - p[0], dy = q[1] - p[1];
    const g = gcd(dx, dy);
    dx /= g; dy /= g;
    if (dx < 0 || (dx === 0 && dy < 0)) { dx = -dx; dy = -dy; }
    return `${dx},${dy}`;
  };
  return step(points[0], points[1]) !== step(points[0], points[2]);
}

