function generate(rand, size) {
  const span = size === 'large' ? 100 : 4;
  const pick = () => Math.floor(rand() * (span + 1));
  if (rand() < 0.4) {
    // Build three points on one line through a random point.
    for (;;) {
      const x = pick(), y = pick();
      const a = Math.floor(rand() * 7) - 3, b = Math.floor(rand() * 7) - 3;
      const k1 = Math.floor(rand() * 9) - 4, k2 = Math.floor(rand() * 9) - 4;
      const points = [[x, y], [x + k1 * a, y + k1 * b], [x + k2 * a, y + k2 * b]];
      if (points.every(([px, py]) => px >= 0 && px <= span && py >= 0 && py <= span)) return [points];
    }
  }
  return [[[pick(), pick()], [pick(), pick()], [pick(), pick()]]];
}
